<?php namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Http\Resources\ProductoResource; use App\Repositories\ProductoRepositoryInterface; use OpenApi\Attributes as OA; #[OA\Schema(schema: "Categoria", type: "object", properties: [new OA\Property(property: "id", type: "integer"), new OA\Property(property: "nombre", type: "string"), new OA\Property(property: "descripcion", type: "string", nullable: true), new OA\Property(property: "imagen", type: "string", nullable: true)])] #[OA\Schema(schema: "Producto", type: "object", properties: [new OA\Property(property: "id", type: "integer"), new OA\Property(property: "nombre", type: "string"), new OA\Property(property: "descripcion", type: "string", nullable: true), new OA\Property(property: "precio", type: "number", format: "float"), new OA\Property(property: "precio_formateado", type: "string"), new OA\Property(property: "imagen", type: "string", nullable: true), new OA\Property(property: "disponible", type: "boolean"), new OA\Property(property: "categoria_id", type: "integer", nullable: true), new OA\Property(property: "categoria", ref: "#/components/schemas/Categoria", nullable: true)])] class ProductoApiController extends Controller { protected $productoRepoInterface; public function __construct(ProductoRepositoryInterface $productoRepoInterface) { $this->productoRepoInterface = $productoRepoInterface; } #[OA\Get(path: "/api/productos", summary: "Lista de productos", description: "Devuelve todos los productos disponibles en la panaderia", tags: ["Productos"], responses: [new OA\Response(response: 200, description: "Operación exitosa", content: new OA\JsonContent(type: "object", properties: [new OA\Property(property: "data", type: "array", items: new OA\Items(ref: "#/components/schemas/Producto"))]))])] public function index() { return ProductoResource::collection($this->productoRepoInterface->all()); } #[OA\Get(path: "/api/productos/{id}", summary: "Consultar producto", description: "Devuelve un producto según su identificador", tags: ["Productos"], parameters: [new OA\Parameter(name: "id", in: "path", required: true, schema: new OA\Schema(type: "integer"))], responses: [new OA\Response(response: 200, description: "Producto encontrado", content: new OA\JsonContent(type: "object", properties: [new OA\Property(property: "data", ref: "#/components/schemas/Producto")])), new OA\Response(response: 404, description: "Producto no encontrado", content: new OA\JsonContent(properties: [new OA\Property(property: "message", type: "string", example: "Producto no encontrado")]))])] public function show(int $id) { $producto = $this->productoRepoInterface->find($id); if (!$producto) { return response()->json(["message" => "Producto no encontrado"], 404); } return new ProductoResource($producto); } }
